    DeliveryStreamDescription.add_member(:delivery_stream_status, Smithy::Schema::Shapes::ShapeRef.new(shape: DeliveryStreamStatus, location_name: 'DeliveryStreamStatus', traits: {"smithy.api#documentation" => "<p>The status of the Firehose stream. If the status of a Firehose stream is\n            <code>CREATING_FAILED</code>, this status doesn't change, and you can't invoke\n            <code>CreateDeliveryStream</code> again on it. However, you can invoke the <a>DeleteDeliveryStream</a> operation to delete it.</p>", "smithy.api#required" => {}}))
    DeliveryStreamDescription.add_member(:failure_description, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureDescription, location_name: 'FailureDescription', traits: {"smithy.api#documentation" => "<p>Provides details in case one of the following operations fails due to an error related\n         to KMS: <a>CreateDeliveryStream</a>, <a>DeleteDeliveryStream</a>,\n            <a>StartDeliveryStreamEncryption</a>, <a>StopDeliveryStreamEncryption</a>.</p>"}))
    DeliveryStreamDescription.add_member(:delivery_stream_encryption_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DeliveryStreamEncryptionConfiguration, location_name: 'DeliveryStreamEncryptionConfiguration', traits: {"smithy.api#documentation" => "<p>Indicates the server-side encryption (SSE) status for the Firehose stream.</p>"}))
    DeliveryStreamDescription.add_member(:delivery_stream_type, Smithy::Schema::Shapes::ShapeRef.new(shape: DeliveryStreamType, location_name: 'DeliveryStreamType', traits: {"smithy.api#documentation" => "<p>The Firehose stream type. This can be one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DirectPut</code>: Provider applications access the Firehose stream\n               directly.</p>\n            </li>\n            <li>\n               <p>\n                  <code>KinesisStreamAsSource</code>: The Firehose stream uses a Kinesis data\n               stream as a source.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    DeliveryStreamDescription.add_member(:version_id, Smithy::Schema::Shapes::ShapeRef.new(shape: DeliveryStreamVersionId, location_name: 'VersionId', traits: {"smithy.api#documentation" => "<p>Each time the destination is updated for a Firehose stream, the version ID is\n         changed, and the current version ID is required when updating the destination. This is so\n         that the service knows it is applying the changes to the correct version of the delivery\n         stream.</p>", "smithy.api#required" => {}}))
