    DeliveryStreamDescription.add_member(:source, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceDescription, location_name: 'Source', traits: {"smithy.api#documentation" => "<p>If the <code>DeliveryStreamType</code> parameter is\n            <code>KinesisStreamAsSource</code>, a <a>SourceDescription</a> object\n         describing the source Kinesis data stream.</p>"}))
