    ElasticsearchBufferingHints.add_member(:size_in_m_bs, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchBufferingSizeInMBs, location_name: 'SizeInMBs', traits: {"smithy.api#documentation" => "<p>Buffer incoming data to the specified size, in MBs, before delivering it to the\n         destination. The default value is 5.</p>\n         <p>We recommend setting this parameter to a value greater than the amount of data you\n         typically ingest into the Firehose stream in 10 seconds. For example, if you typically\n         ingest data at 1 MB/sec, the value should be 10 MB or higher.</p>"}))
    ElasticsearchBufferingHints.type = Types::ElasticsearchBufferingHints
    ElasticsearchDestinationConfiguration.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleARN, location_name: 'RoleARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM role to be assumed by Firehose\n         for calling the Amazon OpenSearch Service Configuration API and for indexing documents. For more\n         information, see <a href=\"https://docs.aws.amazon.com/firehose/latest/dev/controlling-access.html#using-iam-s3\">Grant Firehose Access to an Amazon S3 Destination</a> and <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws-arns-and-namespaces.html\">Amazon Resource Names (ARNs) and\n               Amazon Web Services Service Namespaces</a>.</p>", "smithy.api#required" => {}}))
    ElasticsearchDestinationConfiguration.add_member(:domain_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchDomainARN, location_name: 'DomainARN', traits: {"smithy.api#documentation" => "<p>The ARN of the Amazon OpenSearch Service domain. The IAM role must have permissions\n            for <code>DescribeDomain</code>, <code>DescribeDomains</code>, and\n            <code>DescribeDomainConfig</code> after assuming the role specified in <b>RoleARN</b>. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws-arns-and-namespaces.html\">Amazon Resource Names (ARNs) and\n               Amazon Web Services Service Namespaces</a>.</p>\n         <p>Specify either <code>ClusterEndpoint</code> or <code>DomainARN</code>.</p>"}))
    ElasticsearchDestinationConfiguration.add_member(:cluster_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchClusterEndpoint, location_name: 'ClusterEndpoint', traits: {"smithy.api#documentation" => "<p>The endpoint to use when communicating with the cluster. Specify either this\n            <code>ClusterEndpoint</code> or the <code>DomainARN</code> field.</p>"}))
    ElasticsearchDestinationConfiguration.add_member(:index_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchIndexName, location_name: 'IndexName', traits: {"smithy.api#documentation" => "<p>The Elasticsearch index name.</p>", "smithy.api#required" => {}}))
    ElasticsearchDestinationConfiguration.add_member(:type_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchTypeName, location_name: 'TypeName', traits: {"smithy.api#documentation" => "<p>The Elasticsearch type name. For Elasticsearch 6.x, there can be only one type per\n         index. If you try to specify a new type for an existing index that already has another\n         type, Firehose returns an error during run time.</p>\n         <p>For Elasticsearch 7.x, don't specify a <code>TypeName</code>.</p>"}))
    ElasticsearchDestinationConfiguration.add_member(:index_rotation_period, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchIndexRotationPeriod, location_name: 'IndexRotationPeriod', traits: {"smithy.api#documentation" => "<p>The Elasticsearch index rotation period. Index rotation appends a timestamp to the\n            <code>IndexName</code> to facilitate the expiration of old data. For more information,\n         see <a href=\"https://docs.aws.amazon.com/firehose/latest/dev/basic-deliver.html#es-index-rotation\">Index Rotation for the\n            Amazon OpenSearch Service Destination</a>. The default value is <code>OneDay</code>.</p>"}))
    ElasticsearchDestinationConfiguration.add_member(:buffering_hints, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchBufferingHints, location_name: 'BufferingHints', traits: {"smithy.api#documentation" => "<p>The buffering options. If no value is specified, the default values for\n            <code>ElasticsearchBufferingHints</code> are used.</p>"}))
    ElasticsearchDestinationConfiguration.add_member(:retry_options, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchRetryOptions, location_name: 'RetryOptions', traits: {"smithy.api#documentation" => "<p>The retry behavior in case Firehose is unable to deliver documents to\n         Amazon OpenSearch Service. The default value is 300 (5 minutes).</p>"}))
    ElasticsearchDestinationConfiguration.add_member(:s3_backup_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchS3BackupMode, location_name: 'S3BackupMode', traits: {"smithy.api#documentation" => "<p>Defines how documents should be delivered to Amazon S3. When it is set to\n            <code>FailedDocumentsOnly</code>, Firehose writes any documents that could\n         not be indexed to the configured Amazon S3 destination, with\n            <code>AmazonOpenSearchService-failed/</code> appended to the key prefix. When set to\n            <code>AllDocuments</code>, Firehose delivers all incoming records to Amazon\n         S3, and also writes failed documents with <code>AmazonOpenSearchService-failed/</code>\n         appended to the prefix. For more information, see <a href=\"https://docs.aws.amazon.com/firehose/latest/dev/basic-deliver.html#es-s3-backup\">Amazon S3 Backup for the\n            Amazon OpenSearch Service Destination</a>. Default value is\n         <code>FailedDocumentsOnly</code>.</p>\n         <p>You can't change this backup mode after you create the Firehose stream. </p>"}))
    ElasticsearchDestinationConfiguration.add_member(:s3_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: S3DestinationConfiguration, location_name: 'S3Configuration', traits: {"smithy.api#documentation" => "<p>The configuration for the backup Amazon S3 location.</p>", "smithy.api#required" => {}}))
    ElasticsearchDestinationConfiguration.add_member(:processing_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessingConfiguration, location_name: 'ProcessingConfiguration', traits: {"smithy.api#documentation" => "<p>The data processing configuration.</p>"}))
    ElasticsearchDestinationConfiguration.add_member(:cloud_watch_logging_options, Smithy::Schema::Shapes::ShapeRef.new(shape: CloudWatchLoggingOptions, location_name: 'CloudWatchLoggingOptions', traits: {"smithy.api#documentation" => "<p>The Amazon CloudWatch logging options for your Firehose stream.</p>"}))
    ElasticsearchDestinationConfiguration.add_member(:vpc_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcConfiguration, location_name: 'VpcConfiguration', traits: {"smithy.api#documentation" => "<p>The details of the VPC of the Amazon destination.</p>"}))
