    ElasticsearchDestinationDescription.add_member(:domain_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchDomainARN, location_name: 'DomainARN', traits: {"smithy.api#documentation" => "<p>The ARN of the Amazon OpenSearch Service domain. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws-arns-and-namespaces.html\">Amazon\n            Resource Names (ARNs) and Amazon Web Services Service Namespaces</a>.</p>\n         <p>Firehose uses either <code>ClusterEndpoint</code> or <code>DomainARN</code>\n         to send data to Amazon OpenSearch Service.</p>"}))
    ElasticsearchDestinationDescription.add_member(:cluster_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchClusterEndpoint, location_name: 'ClusterEndpoint', traits: {"smithy.api#documentation" => "<p>The endpoint to use when communicating with the cluster. Firehose uses\n         either this <code>ClusterEndpoint</code> or the <code>DomainARN</code> field to send data\n         to Amazon OpenSearch Service.</p>"}))
